{
  "implementation": "def solve(case):
    items = case['items']
    required = set(case['required_failure_items'])
    unresolved_without = set(case['unresolved_without'])

    def test(config):
        config_set = set(config)
        if required.issubset(config_set):
            return 'FAIL'
        elif any(item not in config_set for item in unresolved_without):
            return 'UNRESOLVED'
        else:
            return 'PASS'

    current = list(items)
    tests = 1
    outcome = test(current)
    if outcome != 'FAIL':
        return {'minimal_failure': current, 'outcome': outcome, 'tests': tests}

    n = 2
    while True:
        if n > len(current):
            n = len(current)
        # partition current into n subsets
        subsets = []
        size = len(current) // n
        remainder = len(current) % n
        start = 0
        for i in range(n):
            extra = 1 if i < remainder else 0
            end = start + size + extra
            subsets.append(current[start:end])
            start = end
        # test subsets
        found_fail = False
        for subset in subsets:
            res = test(subset)
            tests += 1
            if res == 'FAIL':
                current = subset
                n = 2
                found_fail = True
                break
        if not found_fail:
            # test complements
            for subset in subsets:
                complement = [item for item in current if item not in subset]
                res = test(complement)
                tests += 1
                if res == 'FAIL':
                    current = complement
                    n = 2
                    found_fail = True
                    break
        if not found_fail:
            if n == len(current):
                break
            n = min(n * 2, len(current))

    return {'minimal_failure': current, 'outcome': 'FAIL', 'tests': tests}"
}
